INSERT INTO parametros (chave, valor) VALUES ('mail.template.suporte.faleconosco', '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd"><html xmlns="http://www.w3.org/1999/xhtml"> <head> <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/> <title>DEZI</title> <meta name="viewport" content="width=device-width, initial-scale=1.0"/> </head> <body style="color: rgb(55,71,79);font-family: ''Helvetica Neue'', Helvetica, Arial, sans-serif;font-size: 18px;text-align: justify;"> <table align="center" border="0" cellpadding="0" cellspacing="0" width="800"> <tr> <td align="center" bgcolor="#9EB44D" style="padding: 40px 0 30px 0;"> </td></tr><tr> <td bgcolor="#ffffff" style="padding: 40px 30px 40px 30px;"> <div style="margin: 0 auto;">  <h3 style="font-size: 20px;font-weight: bold;">  Prezado Suporte, </h3>  <p> Foi solicitado uma ajuda, por --nomeremetente--, com e-mail --emailremetente--, através do aplicativo Dezi.  <br><br>  Segue abaixo os detalhes da demanda: <br><br>  <strong>Plataforma do Aplicativo: </strong>--plataforma--<br><br> <strong>Classificação: </strong>--classificacao--<br><br> <strong>Mensagem: </strong> --mensagem-- <br><br>Atenciosamente, <br>  <strong>A App Dezi.</strong> </p></div></td></tr><tr> <td align="center" bgcolor="#9EB44D" style="padding: 40px 0 30px 0;">  </td></tr></table> </body></html>')
